/**
 * Recurring issue rules. Tenant reads are org-scoped; the job's sweep is
 * cross-tenant on purpose.
 */
import { and, asc, count, eq, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, recurringIssues } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import type { RecurringIssueRow } from "@/server/db/schema/recurring-issues";
import type { CreateRecurringIssueInput } from "@/schemas/recurring-issue";
import type { IsoTimestamp, OrgId, ProjectId, UserId } from "@/types/common";
import type { RecurringIssue } from "@/types/recurring-issue";

function toRule(row: RecurringIssueRow): RecurringIssue {
  return {
    id: row.id,
    orgId: row.orgId as OrgId,
    projectId: row.projectId as ProjectId,
    title: row.title,
    priority: row.priority,
    assigneeId: row.assigneeId as UserId | null,
    cadence: row.cadence,
    weekday: row.weekday,
    timezone: row.timezone,
    startsOn: row.startsOn,
    lastOccurrenceOn: row.lastOccurrenceOn,
    paused: row.paused,
    createdBy: row.createdBy as UserId,
    createdAt: row.createdAt as IsoTimestamp,
    updatedAt: row.updatedAt as IsoTimestamp,
  };
}

export async function insertRecurringIssue(
  input: {
    orgId: OrgId;
    projectId: ProjectId;
    title: string;
    priority: RecurringIssue["priority"];
    assigneeId: UserId | null;
    cadence: RecurringIssue["cadence"];
    weekday: number | null;
    timezone: string;
    startsOn: string;
  },
  createdBy: UserId,
): Promise<RecurringIssue> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(recurringIssues)
    .values({
      id: newId(),
      orgId: input.orgId,
      projectId: input.projectId,
      title: input.title,
      priority: input.priority,
      assigneeId: input.assigneeId,
      cadence: input.cadence,
      weekday: input.weekday,
      timezone: input.timezone,
      startsOn: input.startsOn,
      lastOccurrenceOn: null,
      paused: false,
      createdBy,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();
  return toRule(row);
}

export type { CreateRecurringIssueInput };

export async function findRecurringIssue(
  orgId: OrgId,
  id: string,
): Promise<RecurringIssue | null> {
  const row = getDb()
    .select()
    .from(recurringIssues)
    .where(
      and(orgPredicate(recurringIssues.orgId, orgId), eq(recurringIssues.id, id)),
    )
    .get();
  return row ? toRule(row) : null;
}

export async function listRecurringIssues(
  orgId: OrgId,
): Promise<readonly RecurringIssue[]> {
  return getDb()
    .select()
    .from(recurringIssues)
    .where(orgPredicate(recurringIssues.orgId, orgId))
    .orderBy(asc(recurringIssues.createdAt), sql`rowid`)
    .all()
    .map(toRule);
}

/** Every rule counts against the quota, paused or not. */
export async function countRecurringIssues(orgId: OrgId): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(recurringIssues)
    .where(orgPredicate(recurringIssues.orgId, orgId))
    .get();
  return row?.value ?? 0;
}

/** Cross-tenant, for the background job. */
export async function listActiveRecurringIssues(): Promise<
  readonly RecurringIssue[]
> {
  return getDb()
    .select()
    .from(recurringIssues)
    .where(eq(recurringIssues.paused, false))
    .orderBy(asc(recurringIssues.createdAt), sql`rowid`)
    .all()
    .map(toRule);
}

export async function setPaused(
  orgId: OrgId,
  id: string,
  paused: boolean,
): Promise<RecurringIssue | null> {
  const row = getDb()
    .update(recurringIssues)
    .set({ paused, updatedAt: toIsoTimestamp(new Date()) })
    .where(
      and(orgPredicate(recurringIssues.orgId, orgId), eq(recurringIssues.id, id)),
    )
    .returning()
    .get();
  return row ? toRule(row) : null;
}

export async function setLastOccurrence(
  orgId: OrgId,
  id: string,
  occurrenceOn: string,
): Promise<void> {
  getDb()
    .update(recurringIssues)
    .set({
      lastOccurrenceOn: occurrenceOn,
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(
      and(orgPredicate(recurringIssues.orgId, orgId), eq(recurringIssues.id, id)),
    )
    .run();
}
